fn has_only_one_distinct_element(a: &Vec<i32>) -> bool
// ensures: returns true if and only if `a` contains zero or one distinct element
// specifically:
//  - if `a` is empty, result is true
//  - otherwise, all elements are equal to a[0]
{
    // When `a` is empty, by definition it has only one distinct element (none), so true
    if a.is_empty() {
        return true;
    }

    let first = a[0];

    // Postcondition justification:
    // The result is true if all elements x in a satisfy x == first,
    // meaning the number of distinct elements is at most one.
    a.iter().all(|&x| x == first)
}